"""Import owner's approved public copy, preserving complete source text (no legal rewriting)."""
import pathlib,json,hashlib,re
r=pathlib.Path(__file__).resolve().parents[2]
def read_literal(path,marker):
 s=path.read_text();a=s.index('=',s.index(marker))+1;tail=s[a:];space=len(tail)-len(tail.lstrip());d,n=json.JSONDecoder().raw_decode(tail.lstrip());return s[:a],d,s[a+space+n:]
p=r/'mobile/src/content/legalDocuments.ts';prefix,docs,suffix=read_literal(p,'export const legalDocuments')
q=r/'mobile/src/content/sitePages.ts';qp,pages,qs=read_literal(q,'export const sitePages:')
ids=['privacy','consent','cookies','recommendations'];names=['Политика в отношении обработки персональных данных','Согласие на обработку персональных данных','Политика использования cookie и аналогичных технологий','Правила применения рекомендательных технологий'];urls=['privacy-policy','user-agreement','cookie-policy','recom-tech-info'];google=['1jQTIAnYXpT1CMPiAQ2gTlnH3i8K8eoT8_y7n9pLAwvQ','19glQU6fzLkXspIT_zEeZWr77VMk7t7JuknPxV453FJ4','1umB1adehHQ2VZzkn_HyVQMKVMLTs2wQXGoFgbHgZqoA','15raJMyslzGZJOc-4agQF6GqsXIy7pb6KvtOf_Fup0rg','1NhDCF-QTY5H29ng0gYH_F7_hGmJO81qSHC3VWaVNDRQ'];manifest={}
for i,key in enumerate(ids):
 path=f'docs/legal41/source/{i+1:02}.txt';txt=(r/path).read_text();sha=hashlib.sha256(txt.encode()).hexdigest();url='https://docs.google.com/document/d/'+google[i]+'/edit'
 docs[key].update(title=names[i],content=txt,originalContent=txt,sourceTextSha256=sha,sourceUrl=url,sourceFiles=[path],checkedAt='2026-09-18',draftDomainMigration={'from':[],'to':'https://prom23.ru','applied':False})
 manifest[key]={'edition':'2026-10-01','sha256':sha,'sourceUrl':url,'sourceFile':path}
 for page in pages.values():
  if page.get('sourceUrl','') and '/'+urls[i]+'/' in page['sourceUrl']:
   page.update(title=names[i],sections=[{'id':'approved-2026-10-01','paragraphs':re.split(r'\n\s*\n',txt.strip())}],links=[],sourceReviewRequired=[])
p.write_text(prefix+' '+json.dumps(docs,ensure_ascii=False,indent=2)+suffix)
q.write_text(qp+' '+json.dumps(pages,ensure_ascii=False,indent=2)+qs)
raw=(r/'docs/legal41/source/05.txt').read_text();sections=re.split(r'\n\n+\d+\. [^\n]+\n\n+',raw)[1:]
# Paragraphs are extracted, not paraphrased. Technical placement instructions remain internal.
paras=lambda n: [x.strip() for x in re.split(r'\n\s*\n',sections[n-1]) if x.strip()]
copy={'edition':'2026-10-01','recommendations':paras(1)[0],'cookieBanner':'\n\n'.join(paras(2)[:2]),'processing':paras(4)[1].removeprefix('☐ '),'marketing':paras(5)[1].removeprefix('☐ '),'registration':paras(6)[1],'checkoutPersonal':paras(7)[1],'checkoutBusiness':paras(8)[1],'card':paras(9)[1],'yandexPay':paras(10)[1],'split':paras(11)[1],'savedPayment':paras(12)[2].removeprefix('Пояснение:\n'),'address':paras(13)[1],'upload':paras(14)[1],'serviceConsent':paras(15)[1].removeprefix('☐ '),'service':paras(16)[1],'personalization':paras(17)[1],'rejected':paras(18)[1],'contact':paras(20)[1]}
copy['cookieCategories']=[{'id':key,'title':p.split('\n')[0],'description':'\n'.join(p.split('\n')[1:])} for key,p in zip(['necessary','functional','analytics','advertising','personalization'],paras(3))]
(r/'mobile/src/content/legalCopy.ts').write_text('// Exact UI copy from approved document 05; regenerated by scripts/legal/import-approved.py.\nexport const legalCopy = '+json.dumps(copy,ensure_ascii=False,indent=2)+' as const;\n')
manifest['ui']={'edition':'2026-10-01','sha256':hashlib.sha256(raw.encode()).hexdigest(),'sourceUrl':'https://docs.google.com/document/d/'+google[4]+'/edit','sourceFile':'docs/legal41/source/05.txt'}
(r/'docs/legal41/source-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
(r/'integrations/runtime/legal-versions.json').write_text(json.dumps({key:{'version':row['edition'],'sha256':row['sha256']} for key,row in manifest.items()},ensure_ascii=False,indent=2)+'\n')
print('Imported complete approved documents and UI copy')
